        for expr in &group_by {
            let idx = scope.add_aggregate(expr, scope);
            if let Some(idx) = idx {
                // Already added
            } else {
                let expr = Self::build_expression(expr.clone(), scope)?;
                let idx = scope.add_column(expr.into());
                scope.add_aggregate(expr, scope);
            }
        }

        // Add aggregate expressions to scope
        for expr in &aggregates {
            let idx = scope.add_aggregate(expr, scope);
            if idx.is_none() {
                let expr = Self::build_expression(expr.clone(), scope)?;
                let agg = Self::build_aggregate_function(expr, scope)?;
                let idx = scope.add_column(expr.into());
                scope.add_aggregate(expr, scope);
            }
        }

        Ok(Node::Aggregate {
            source: Box::new(source),
            group_by,
            aggregates,
        })
    }

    /// Builds an aggregate function from an AST expression.
    fn build_aggregate_function(expr: ast::Expression, scope: &Scope) -> Result<Aggregate> {
        if let ast::Expression::Function(name, args) = expr {
            let name = name.to_uppercase();
            match name.as_str() {
                "COUNT" => {
                    if args.len() != 1 {
                        return errinput!("COUNT requires exactly one argument");
                    }
                    let arg = Self::build_expression(args[0].clone(), scope)?;
                    Ok(Aggregate::Count(arg))
                }
                "SUM" => {
                    if args.len() != 1 {
                        return errinput!("SUM requires exactly one argument");
                    }
                    let arg = Self::build_expression(args[0].clone(), scope)?;
                    Ok(Aggregate::Sum(arg))
                }
                "AVG" => {
                    if args.len() != 1 {
                        return errinput!("AVG requires exactly one argument");
                    }
                    let arg = Self::build_expression(args[0].clone(), scope)?;
                    Ok(Aggregate::Average(arg))
                }
                "MAX" => {
                    if args.len() != 1 {
                        return errinput!("MAX requires exactly one argument");
                    }
                    let arg = Self::build_expression(args[0].clone(), scope)?;
                    Ok(Aggregate::Max(arg))
                }
                "MIN" => {
                    if args.len() != 1 {
                        return errinput!("MIN requires exactly one argument");
                    }
                    let arg = Self::build_expression(args[0].clone(), scope)?;
                    Ok(Aggregate::Min(arg))
                }
                "MEDIAN" => {
                    if args.len() != 1 {
                        return errinput!("MEDIAN requires exactly one argument");
                    }
                    let arg = Self::build_expression(args[0].clone(), scope)?;
                    Ok(Aggregate::Median(arg))
                }
                "STRING_AGG" => {
                    if args.len() != 2 {
                        return errinput!("STRING_AGG requires exactly two arguments");
                    }
                    let arg1 = Self::build_expression(args[0].clone(), scope)?;
                    let arg2 = Self::build_expression(args[1].clone(), scope)?;
                    Ok(Aggregate::StringAgg(arg1, arg2))
                }
                _ => Err(errinput!("unknown aggregate function: {name}")),
            }
        } else {
            Err(errinput!("expected aggregate function"))
        }
    }

    /// Checks whether a given AST expression is an aggregate function.
    fn is_aggregate_function(expr: &ast::Expression) -> bool {
        if let ast::Expression::Function(name, _) = expr {
            let name = name.to_uppercase();
            matches!(
                name.as_str(),
                "COUNT" | "SUM" | "AVG" | "MAX" | "MIN" | "MEDIAN" | "STRING_AGG"
            )
        } else {
            false
        }
    }

    /// Collects aggregate functions from SELECT, HAVING, and ORDER BY clauses.
    fn collect_aggregates(
        select: &[(ast::Expression, Option<String>)],
        having: &Option<ast::Expression>,
        order_by: &[(ast::Expression, ast::Direction)],
    ) -> Vec<ast::Expression> {
        let mut aggregates = Vec::new();

        for (expr, _) in select {
            expr.collect(&Self::is_aggregate_function, &mut aggregates);
        }

        if let Some(expr) = having {
            expr.collect(&Self::is_aggregate_function, &mut aggregates);
        }

        for (expr, _) in order_by {
            expr.collect(&Self::is_aggregate_function, &mut aggregates);
        }

        aggregates
    }

    /// Builds hidden columns for a projection to pass through columns that are
    /// used by downstream nodes.
    fn build_select_hidden(
        &self,
        having: &Option<ast::Expression>,
        order_by: &[(ast::Expression, ast::Direction)],
        scope: &Scope,
        child_scope: &mut Scope,
    ) -> Vec<Expression> {
        let mut hidden = Vec::new();

        if let Some(expr) = having {
            expr.collect(&|e| !matches!(e, ast::Expression::Column(_, _)), &mut hidden);
        }

        for (expr, _) in order_by {
            expr.collect(&|e| !matches!(e, ast::Expression::Column(_, _)), &mut hidden);
        }

        hidden
    }

    /// Builds an expression from an AST expression, looking up columns and
    /// aggregate expressions in the scope.
    pub fn build_expression(expr: ast::Expression, scope: &Scope) -> Result<Expression> {
        match expr {
