/// Pushes filter predicates down into child nodes where possible.
#[derive(Debug)]
pub struct FilterPushdown;

impl Optimizer for FilterPushdown {
    fn optimize(&self, node: Node) -> Result<Node> {
        Ok(Self::push_filters(node))
    }
}

impl FilterPushdown {
    /// Pushes filter predicates down into child nodes where possible.
    fn push_filters(mut node: Node) -> Node {
        node = node.transform(
            &|n| Ok(n),
            &|n| match n {
                Node::Filter { source, predicate } => {
                    let source = Self::push_filters(*source);
                    match Self::maybe_push_filter(Node::Filter { source, predicate }) {
                        Node::Filter { source, predicate } => {
                            Node::Filter { source: Box::new(source), predicate }
                        }
                        other => other,
                    }
                }
                Node::NestedLoopJoin { left, right, predicate, outer } => {
                    let left = Box::new(Self::push_filters(*left));
                    let right = Box::new(Self::push_filters(*right));
                    Self::maybe_push_join(Node::NestedLoopJoin {
                        left,
                        right,
                        predicate,
                        outer,
                    })
                }
                other => other,
            },
        )
        .unwrap();
        node
    }

    /// Pushes an expression into a node if possible.
    fn push_into(expr: Expression, target: &mut Node) -> Option<Expression> {
        match target {
            Node::Scan { filter, .. } => {
                if let Some(f) = filter {
                    *filter = Some(Expression::And(f.clone().into(), expr.into()));
                    None
                } else {
                    *filter = Some(expr);
                    None
                }
            }
            Node::Filter { predicate, .. } => {
                let old = std::mem::replace(predicate, Expression::Constant(Value::Boolean(true)));
                *predicate = Expression::And(old.into(), expr.into());
                None
            }
            Node::NestedLoopJoin { predicate, .. } => {
                if let Some(p) = predicate {
                    *predicate = Some(Expression::And(p.clone().into(), expr.into()));
                    None
                } else {
                    *predicate = Some(expr);
                    None
                }
            }
            _ => Some(expr),
        }
    }

    /// Pushes a filter node predicate down into its source, if possible.
    fn maybe_push_filter(node: Node) -> Node {
        if let Node::Filter { source, predicate } = node {
            match *source {
                Node::Scan { table, filter, alias } => {
                    let filter = if let Some(f) = filter {
                        Some(Expression::And(f, predicate))
                    } else {
                        Some(predicate)
                    };
                    Node::Scan { table, filter, alias }
                }
                Node::Filter { source: inner_source, predicate: inner_predicate } => {
                    Node::Filter {
                        source: inner_source,
                        predicate: Expression::And(inner_predicate, predicate),
                    }
                }
                Node::NestedLoopJoin { left, right, predicate, outer } => {
                    let mut left = *left;
                    let mut right = *right;
                    let mut new_predicate = predicate;

                    if let Some(p) = Self::push_into(predicate.clone(), &mut left) {
                        new_predicate = Some(p);
                    }
                    if let Some(p) = Self::push_into(predicate, &mut right) {
                        new_predicate = Some(p);
                    }

                    Node::NestedLoopJoin {
                        left: Box::new(left),
                        right: Box::new(right),
                        predicate: new_predicate,
                        outer,
                    }
                }
                other => Node::Filter { source: Box::new(other), predicate },
            }
        } else {
            node
        }
    }

    // Pushes down parts of a join predicate into the left or right sources
    // where possible.
    fn maybe_push_join(node: Node) -> Node {
        if let Node::NestedLoopJoin { left, right, predicate, outer } = node {
            let mut left = *left;
            let mut right = *right;
            let mut new_predicate = predicate;

            if let Some(p) = new_predicate.take() {
                if let Some(p) = Self::push_into(p.clone(), &mut left) {
                    new_predicate = Some(p);
                }
                if let Some(p) = Self::push_into(p, &mut right) {
                    new_predicate = Some(p);
                }
            }

            Node::NestedLoopJoin {
                left: Box::new(left),
                right: Box::new(right),
                predicate: new_predicate,
                outer,
            }
        } else {
            node
        }
    }
}

