impl Optimizer for IndexLookup {
    fn optimize(&self, node: Node) -> Result<Node> {
        Ok(Self::index_lookup(node))
    }
}

impl IndexLookup {
    /// Rewrites a filtered scan node into a key or index lookup if possible.
    fn index_lookup(mut node: Node) -> Node {
        node = node.transform(
            &|n| Ok(n),
            &|n| match n {
                Node::Filter { source, predicate } => {
                    let source = Self::index_lookup(*source);
                    Node::Filter {
                        source: Box::new(source),
                        predicate,
                    }
                }
                other => other,
            },
        )
        .unwrap();

        if let Node::Filter { source, predicate } = node {
            if let Node::Scan { table, filter, alias } = *source {
                let filter = if let Some(f) = filter {
                    Expression::And(f, predicate)
                } else {
                    predicate
                };

                // Try to convert to index lookup
                if let Some(col_idx) = filter.is_column_lookup() {
                    let values = filter.into_column_values(col_idx);
                    if !values.is_empty() {
                        return Node::IndexLookup {
                            table,
                            column: col_idx,
                            values,
                            alias,
                        };
                    }
                }

                // Try to convert to key lookup
                if let Some(col_idx) = filter.is_column_lookup() {
                    let values = filter.into_column_values(col_idx);
                    if !values.is_empty() && col_idx == table.primary_key {
                        return Node::KeyLookup {
                            table,
                            keys: values,
                            alias,
                        };
                    }
                }

                Node::Scan {
                    table,
                    filter: Some(filter),
                    alias,
                }
            } else {
                Node::Filter { source, predicate }
            }
        } else {
            node
        }
    }
}

/// Uses a hash join instead of a nested loop join for single-column equijoins.
#[derive(Debug)]
pub struct HashJoin;

impl Optimizer for HashJoin {
    fn optimize(&self, node: Node) -> Result<Node> {
        Ok(Self::hash_join(node))
    }
}

impl HashJoin {
    /// Rewrites a nested loop join into a hash join if possible.
    pub fn hash_join(node: Node) -> Node {
        node.transform(
            &|n| Ok(n),
            &|n| match n {
                Node::NestedLoopJoin { left, right, predicate, outer } => {
                    let left = Box::new(Self::hash_join(*left));
                    let right = Box::new(Self::hash_join(*right));

                    // Check if we can convert to hash join
                    if let Some((left_col, right_col)) = Self::find_equijoin_columns(&predicate) {
                        Node::HashJoin {
                            left,
                            left_column: left_col,
                            right,
                            right_column: right_col,
                            outer,
                        }
                    } else {
                        Node::NestedLoopJoin {
                            left,
                            right,
                            predicate,
                            outer,
                        }
                    }
                }
                other => other,
            },
        )
        .unwrap()
    }

    fn find_equijoin_columns(predicate: &Option<Expression>) -> Option<(usize, usize)> {
        if let Some(expr) = predicate {
            // Look for a simple equality join condition
            if let Expression::Equal(l, r) = expr {
                if let (Expression::Column(l_col), Expression::Column(r_col)) = (l.as_ref(), r.as_ref()) {
                    if *l_col != *r_col {
                        return Some((*l_col, *r_col));
                    }
                }
            }
        }
        None
    }
}

/// Short-circuits useless nodes and expressions.
#[derive(Debug)]
pub struct ShortCircuit;

impl Optimizer for ShortCircuit {
    fn optimize(&self, node: Node) -> Result<Node> {
        Ok(Self::short_circuit(node))
    }
}

impl ShortCircuit {
    /// Short-circuits useless nodes.
    fn short_circuit(mut node: Node) -> Node {
        node = node.transform(
            &|n| Ok(n),
            &|n| match n {
                Node::Filter { source, predicate } => {
                    let source = Box::new(Self::short_circuit(*source));
                    if let Expression::Constant(Value::Boolean(true)) = &predicate {
                        *source
                    } else if let Expression::Constant(Value::Boolean(false)) = &predicate {
                        Node::Nothing { columns: source.columns() }
                    } else {
                        Node::Filter { source, predicate }
                    }
                }
                Node::Limit { source, limit } => {
                    let source = Box::new(Self::short_circuit(*source));
                    if *limit == 0 {
                        Node::Nothing { columns: source.columns() }
                    } else {
                        Node::Limit { source, limit: *limit }
                    }
                }
                Node::Offset { source, offset } => {
                    let source = Box::new(Self::short_circuit(*source));
                    if *offset == 0 {
                        *source
                    } else {
                        Node::Offset { source, offset: *offset }
                    }
                }
                Node::Remap { source, targets } => {
                    let source = Box::new(Self::short_circuit(*source));
                    if targets.iter().all(|t| t.is_some()) {
                        Node::Remap { source, targets }
                    } else {
                        // Check if all targets are None
                        if targets.iter().all(|t| t.is_none()) {
                            Node::Nothing { columns: source.columns() }
                        } else {
                            Node::Remap { source, targets }
                        }
                    }
                }
                Node::Projection { source, expressions, aliases } => {
                    let source = Box::new(Self::short_circuit(*source));
                    Node::Projection {
                        source,
                        expressions,
                        aliases,
                    }
                }
                Node::Aggregate { source, group_by, aggregates } => {
                    let source = Box::new(Self::short_circuit(*source));
                    Node::Aggregate {
                        source,
                        group_by,
                        aggregates,
                    }
                }
                Node::Order { source, key } => {
                    let source = Box::new(Self::short_circuit(*source));
                    Node::Order { source, key }
                }
                Node::HashJoin { left, left_column, right, right_column, outer } => {
                    let left = Box::new(Self::short_circuit(*left));
                    let right = Box::new(Self::short_circuit(*right));
                    Node::HashJoin {
                        left,
                        left_column,
                        right,
                        right_column,
                        outer,
                    }
                }
                Node::NestedLoopJoin { left, right, predicate, outer } => {
                    let left = Box::new(Self::short_circuit(*left));
                    let right = Box::new(Self::short_circuit(*right));
                    Node::NestedLoopJoin {
                        left,
                        right,
                        predicate,
                        outer,
                    }
                }
                other => other,
            },
        )
        .unwrap()
    }
}

